use anyhow::Result;
use clap::{Parser, Subcommand};
use pulldown_cmark::{Event, Parser as MarkdownParser, Tag};
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

#[derive(Parser)]
#[command(name = "treemd")]
#[command(version = "0.5.7")]
#[command(about = "A modern markdown viewer combining tree-based navigation with interactive TUI.", long_about = None)]
struct Cli {
    #[arg(help = "Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin")]
    files: Vec<String>,

    #[arg(short, long, help = "List all headings in the document (non-interactive)")]
    list: bool,

    #[arg(long, help = "Show heading tree structure with box-drawing characters (non-interactive)")]
    tree: bool,

    #[arg(long, value_name = "PATTERN", help = "Filter headings by text pattern (case-insensitive)")]
    filter: Option<String>,

    #[arg(short = 'L', long, value_name = "LEVEL", help = "Show only headings at specific level (1-6)")]
    level: Option<u32>,

    #[arg(short, long, value_name = "OUTPUT", default_value = "plain", help = "Output format for --list and --tree modes")]
    output: String,

    #[arg(short, long, value_name = "HEADING", help = "Extract specific section by heading name")]
    section: Option<String>,

    #[arg(long, help = "Count headings by level (shows statistics)")]
    count: bool,

    #[subcommand]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    AtLine {
        #[arg(help = "Line number in the markdown file")]
        line: usize,
    },
}

#[derive(Debug, Clone)]
struct Heading {
    level: u32,
    title: String,
    line: usize,
    content_range: (usize, usize),
}

fn parse_headings(content: &str) -> Vec<Heading> {
    let mut headings = Vec::new();
    let parser = MarkdownParser::new(content);

    let mut current_heading: Option<(u32, String, usize)> = None;

    // pulldown-cmark doesn't easily give line numbers for headings in 0.9.
    // We might need to manually find them or use a different approach.
    // Actually, let's just parse the content line by line to find headings starting with #.

    for (idx, line) in content.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            let mut level = 0;
            let mut chars = trimmed.chars();
            while let Some('#') = chars.next() {
                level += 1;
            }
            let rest = chars.as_str().trim();
            if level > 0 && level <= 6 && (trimmed.chars().nth(level) == Some(' ') || trimmed.chars().nth(level).is_none()) {
                headings.push(Heading {
                    level,
                    title: rest.to_string(),
                    line: idx + 1,
                    content_range: (0, 0), // To be filled
                });
            }
        }
    }

    headings
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let input = if cli.files.is_empty() || cli.files[0] == "-" {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    } else {
        // For now just handle the first file
        fs::read_to_string(&cli.files[0])?
    };

    if cli.list {
        let headings = parse_headings(&input);
        for h in headings {
            if let Some(level_filter) = cli.level {
                if h.level != level_filter {
                    continue;
                }
            }
            if let Some(ref pattern) = cli.filter {
                if !h.title.to_lowercase().contains(&pattern.to_lowercase()) {
                    continue;
                }
            }
            println!("{} {}", "#".repeat(h.level as usize), h.title);
        }
        return Ok(());
    }

    if cli.count {
        let headings = parse_headings(&input);
        let mut counts = [0u32; 7];
        for h in &headings {
            if h.level <= 6 {
                counts[h.level as usize] += 1;
            }
        }
        println!("Heading counts:");
        for i in 1..=6 {
            if counts[i] > 0 {
                println!("  {}: {}", "#".repeat(i), counts[i]);
            }
        }
        println!("\nTotal: {}", headings.len());
        return Ok(());
    }

    Ok(())
}
EOF
"}

