{"command":"cat <<'EOF' > treemd.py
#!/usr/bin/env python3
import sys
import re
import json
import argparse
import curses

def slugify(text):
    text = text.lower()
    text = re.sub(r'[^\w\s-]', '', text)
    text = re.sub(r'[-\s]+', '-', text).strip('-')
    return text

def parse_markdown(content):
    lines = content.splitlines()
    headings = []
    in_code_block = False
    for i, line in enumerate(lines):
        if line.strip().startswith('```'):
            in_code_block = not in_code_block
            continue
        if in_code_block:
            continue
        match = re.match(r'^(#+)\s+(.*)', line)
        if match:
            level = len(match.group(1))
            title = match.group(2).strip()
            if 1 <= level <= 6:
                headings.append({'level': level, 'title': title, 'line': i + 1})
    return headings

def parse_full(content):
    lines = content.splitlines()
    headings = []
    blocks = []
    in_code_block = False
    code_lang = ""
    code_content = []
    for i, line in enumerate(lines):
        if line.strip().startswith('```'):
            if not in_code_block:
                in_code_block = True
                code_lang = line.strip()[3:].strip()
                code_content = []
            else:
                in_code_block = False
                b = {'type': 'code', 'language': code_lang, 'content': '\n'.join(code_content), 'line': i - len(code_content)}
                blocks.append(b)
            continue
        if in_code_block:
            code_content.append(line)
            continue
        h_match = re.match(r'^(#+)\s+(.*)', line)
        if h_match:
            level = len(h_match.group(1))
            title = h_match.group(2).strip()
            if 1 <= level <= 6:
                h = {'type': 'heading', 'level': level, 'title': title, 'line': i + 1}
                headings.append(h)
                blocks.append(h)
                continue
        imgs = re.findall(r'!\[([^\]]*)\]\(([^)]+)\)', line)
        for alt, src in imgs:
            blocks.append({'type': 'image', 'text': alt, 'src': src, 'line': i + 1})
        links = re.findall(r'(?<!\!)\[([^\]]+)\]\(([^)]+)\)', line)
        for text, url in links:
            blocks.append({'type': 'link', 'text': text, 'url': url, 'line': i + 1})
    return headings, blocks

def get_heading_tree(headings):
    root = []
    stack = []
    for h in headings:
        node = {'level': h['level'], 'title': h['title'], 'children': []}
        while stack and stack[-1]['level'] >= h['level']:
            stack.pop()
        if not stack:
            root.append(node)
        else:
            stack[-1]['children'].append(node)
        stack.append(node)
    return root

def render_tree(nodes, prefix=""):
    for i, node in enumerate(nodes):
        is_last = (i == len(nodes) - 1)
        connector = "└──" if is_last else "├──"
        print(f"{prefix}{connector}{'#' * node['level']} {node['title']}")
        new_prefix = prefix + ("   " if is_last else "│  ")
        render_tree(node['children'], new_prefix)

def get_sections_json(headings, content):
    lines = content.splitlines(keepends=True)
    line_offsets = [0]
    total_offset = 0
    for line in lines:
        total_offset += len(line)
        line_offsets.append(total_offset)

    sections = []
    for i, h in enumerate(headings):
        start_line_idx = h['line'] # 1-indexed, so h['line'] is the line after heading if we consider 0-indexing
        end_line_idx = len(lines)
        for j in range(i + 1, len(headings)):
            if headings[j]['level'] <= h['level']:
                end_line_idx = headings[j]['line'] - 1
                break

        raw_content = ''.join(lines[start_line_idx:end_line_idx]).strip('\n')

        section = {
            'id': slugify(h['title']),
            'level': h['level'],
            'title': h['title'],
            'slug': slugify(h['title']),
            'position': {
                'line': h['line'] + 1 if h['line'] < len(lines) else h['line'],
                'offset': line_offsets[h['line']] if h['line'] < len(line_offsets) else line_offsets[-1]
            },
            'content': {'raw': raw_content, 'blocks': []},
            'children': []
        }
        sections.append(section)

    root_sections = []
    stack = []
    for s in sections:
        while stack and stack[-1]['level'] >= s['level']:
            stack.pop()
        if not stack:
            root_sections.append(s)
        else:
            stack[-1]['children'].append(s)
        stack.append(s)
    return root_sections

def extract_section(content, section_name):
    lines = content.splitlines()
    start_line = -1
    section_level = -1
    for i, line in enumerate(lines):
        match = re.match(r'^(#+)\s+(.*)', line)
        if match:
            level = len(match.group(1))
            title = match.group(2).strip()
            if title.lower() == section_name.lower():
                start_line = i
                section_level = level
                break
    if start_line == -1: return ""
    result = [lines[start_line]]
    for i in range(start_line + 1, len(lines)):
        line = lines[i]
        match = re.match(r'^(#+)\s+(.*)', line)
        if match:
            if len(match.group(1)) <= section_level:
                break
        result.append(line)
    return '\n'.join(result)

def execute_query(query, content):
    headings, blocks = parse_full(content)
    current_set = []
    parts = [p.strip() for p in query.split('|')]
    selector_part = parts[0]
    match = re.match(r'^(\.[a-z0-9]+)(?:\[(.*)\])?', selector_part)
    if not match: return []
    tag = match.group(1)
    filter_val = match.group(2)

    if tag == '.h' or tag == '.heading': current_set = headings
    elif re.match(r'\.h[1-6]', tag):
        level = int(tag[2])
        current_set = [h for h in headings if h.get('level') == level]
    elif tag == '.code': current_set = [b for b in blocks if b['type'] == 'code']
    elif tag == '.link' or tag == '.a': current_set = [b for b in blocks if b['type'] == 'link']
    elif tag == '.img': current_set = [b for b in blocks if b['type'] == 'image']
    elif tag == '.': current_set = [{'type': 'doc', 'content': content}]

    if filter_val:
        try:
            idx = int(filter_val)
            if 0 <= idx < len(current_set): current_set = [current_set[idx]]
            elif idx < 0 and abs(idx) <= len(current_set): current_set = [current_set[idx]]
            else: current_set = []
        except ValueError:
            current_set = [item for item in current_set if filter_val.lower() in (item.get('title') or item.get('text', '')).lower()]

    for pipe in parts[1:]:
        if pipe == 'text':
            current_set = [{'type': 'text', 'value': (item.get('title') or item.get('text') or item.get('value') or '')} for item in current_set]
        elif pipe in ('count', 'length', 'len'):
            current_set = [{'type': 'text', 'value': str(len(current_set))}]
            break
        elif pipe == 'slugify':
            current_set = [{'type': 'text', 'value': slugify(item.get('title') or item.get('text') or '')} for item in current_set]
        elif pipe == 'url':
            current_set = [{'type': 'text', 'value': item.get('url') or item.get('src') or ''} for item in current_set]

    output = []
    for item in current_set:
        if item.get('type') == 'heading': output.append(f"{'#' * item['level']} {item['title']}")
        elif item.get('type') == 'code': output.append(f"```{item['language']}\n{item['content']}\n```")
        elif item.get('type') == 'link': output.append(f"[{item['text']}]({item['url']})")
        elif item.get('type') == 'image': output.append(f"![{item['text']}]({item['src']})")
        elif item.get('type') == 'text': output.append(item['value'])
        elif item.get('type') == 'doc': output.append(item['content'])
    return output

def tui_main(stdscr, content):
    headings = parse_markdown(content)
    if not headings:
        stdscr.addstr(0, 0, "No headings found.")
        stdscr.refresh()
        stdscr.getch()
        return

    curses.init_pair(1, curses.COLOR_CYAN, curses.COLOR_BLACK)
    curses.init_pair(2, curses.COLOR_WHITE, curses.COLOR_BLUE)

    current_idx = 0
    while True:
        stdscr.clear()
        height, width = stdscr.getmaxyx()

        # Draw left pane (headings)
        for i, h in enumerate(headings):
            if i >= height - 2: break
            attr = curses.color_pair(2) if i == current_idx else curses.color_pair(1)
            stdscr.addstr(i + 1, 1, f"{' ' * (h['level']-1)}{h['title'][:width//2-5]}", attr)

        # Draw separator
        for i in range(height):
            stdscr.addch(i, width // 2, '|')

        # Draw right pane (content)
        # Simplified: just show a bit of content
        stdscr.addstr(1, width // 2 + 2, "Content View (Sync)")

        stdscr.refresh()
        key = stdscr.getch()
        if key == ord('q'): break
        elif key == curses.KEY_UP or key == ord('k'):
            current_idx = max(0, current_idx - 1)
        elif key == curses.KEY_DOWN or key == ord('j'):
            current_idx = min(len(headings) - 1, current_idx + 1)

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('files', nargs='*')
    parser.add_argument('-l', '--list', action='store_true')
    parser.add_argument('--tree', action='store_true')
    parser.add_argument('--filter')
    parser.add_argument('-L', '--level', type=int)
    parser.add_argument('-o', '--output', default='plain')
    parser.add_argument('-s', '--section')
    parser.add_argument('--count', action='store_true')
    parser.add_argument('-q', '--query')
    parser.add_argument('--version', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')

    # Check for at-line command
    command = None
    line_arg = None
    if len(sys.argv) > 1:
        if sys.argv[1] == 'at-line':
            command = 'at-line'
            if len(sys.argv) > 2: line_arg = sys.argv[2]
        elif len(sys.argv) > 2 and sys.argv[2] == 'at-line':
             # Maybe the file was first
             command = 'at-line'
             if len(sys.argv) > 3: line_arg = sys.argv[3]

    if command == 'at-line':
        input_content = sys.stdin.read()
        headings = parse_markdown(input_content)
        line_num = int(line_arg) if line_arg else 0
        current_heading = None
        for h in headings:
            if h['line'] <= line_num: current_heading = h
            else: break
        if current_heading:
            print(f"{'#' * current_heading['level']} {current_heading['title']}")
        return

    args, unknown = parser.parse_known_args()

    if args.version:
        print("treemd 0.5.7")
        return

    if args.help:
        # Simplified help matching the original's structure
        print("treemd - A modern markdown viewer combining tree-based navigation with interactive TUI.")
        print("\nUsage: executable [OPTIONS] [FILE]... [COMMAND]")
        return

    input_content = ""
    if not args.files or args.files[0] == '-':
        input_content = sys.stdin.read()
    else:
        try:
            with open(args.files[0], 'r') as f:
                input_content = f.read()
        except:
