#!/usr/bin/env python3
import sys
import re
import json
import argparse
import curses

def slugify(text):
    text = text.lower()
    text = re.sub(r'[^\w\s-]', '', text)
    text = re.sub(r'[-\s]+', '-', text).strip('-')
    return text

def parse_markdown(content):
    lines = content.splitlines()
    headings = []
    in_code_block = False
    for i, line in enumerate(lines):
        if line.strip().startswith('```'):
            in_code_block = not in_code_block
            continue
        if in_code_block:
            continue
        match = re.match(r'^(#+)\s+(.*)', line)
        if match:
            level = len(match.group(1))
            title = match.group(2).strip()
            if 1 <= level <= 6:
                headings.append({'level': level, 'title': title, 'line': i + 1})
    return headings

def parse_full(content):
    lines = content.splitlines()
    headings = []
    blocks = []
    in_code_block = False
    code_lang = ""
    code_content = []
    for i, line in enumerate(lines):
        if line.strip().startswith('```'):
            if not in_code_block:
                in_code_block = True
                code_lang = line.strip()[3:].strip()
                code_content = []
            else:
                in_code_block = False
                b = {'type': 'code', 'language': code_lang, 'content': '\n'.join(code_content), 'line': i - len(code_content)}
                blocks.append(b)
            continue
        if in_code_block:
            code_content.append(line)
            continue
        h_match = re.match(r'^(#+)\s+(.*)', line)
        if h_match:
            level = len(h_match.group(1))
            title = h_match.group(2).strip()
            if 1 <= level <= 6:
                h = {'type': 'heading', 'level': level, 'title': title, 'line': i + 1}
                headings.append(h)
                blocks.append(h)
                continue
        imgs = re.findall(r'!\[([^\]]*)\]\(([^)]+)\)', line)
        for alt, src in imgs:
            blocks.append({'type': 'image', 'text': alt, 'src': src, 'line': i + 1})
        links = re.findall(r'(?<!\!)\[([^\]]+)\]\(([^)]+)\)', line)
        for text, url in links:
            blocks.append({'type': 'link', 'text': text, 'url': url, 'line': i + 1})
    return headings, blocks

def get_heading_tree(headings):
    root = []
    stack = []
    for h in headings:
        node = {'level': h['level'], 'title': h['title'], 'children': []}
        while stack and stack[-1]['level'] >= h['level']:
            stack.pop()
        if not stack:
            root.append(node)
        else:
            stack[-1]['children'].append(node)
        stack.append(node)
    return root

def render_tree(nodes, prefix=""):
    for i, node in enumerate(nodes):
        is_last = (i == len(nodes) - 1)
        connector = "└──" if is_last else "├──"
        print(f"{prefix}{connector}{'#' * node['level']} {node['title']}")
        new_prefix = prefix + ("   " if is_last else "│  ")
        render_tree(node['children'], new_prefix)

def get_sections_json(headings, content):
    lines = content.splitlines(keepends=True)
    line_offsets = [0]
    total_offset = 0
    for line in lines:
        total_offset += len(line)
        line_offsets.append(total_offset)

    sections = []
    for i, h in enumerate(headings):
        start_line_idx = h['line'] # 1-indexed, so h['line'] is the line after heading if we consider 0-indexing
        end_line_idx = len(lines)
        for j in range(i + 1, len(headings)):
            if headings[j]['level'] <= h['level']:
                end_line_idx = headings[j]['line'] - 1
                break

        raw_content = ''.join(lines[start_line_idx:end_line_idx]).strip('\n')

