            'id': slugify(h['title']),
            'level': h['level'],
            'title': h['title'],
            'slug': slugify(h['title']),
            'position': {
                'line': h['line'] + 1 if h['line'] < len(lines) else h['line'],
                'offset': line_offsets[h['line']] if h['line'] < len(line_offsets) else line_offsets[-1]
