                        "wordCount": len(input_content.split())
                    },
                    "sections": get_sections_json(headings, input_content)
                }
            }
            print(json.dumps(doc, indent=2))
        else:
            for h in filtered:
                print(f"{'#' * h['level']} {h['title']}")
        return

    if args.tree:
        tree = get_heading_tree(headings)
        render_tree(tree)
        return

    if args.count:
        counts = {}
        for h in headings: counts[h['level']] = counts.get(h['level'], 0) + 1
        print("Heading counts:")
        for l in sorted(counts.keys()):
            print(f"  {'#' * l}: {counts[l]}")
        print(f"\nTotal: {len(headings)}")
        return

    if args.section:
        content = extract_section(input_content, args.section)
        if content: print(content)
        return

    if args.query:
        results = execute_query(args.query, input_content)
        for r in results: print(r)
        return

    # Default: TUI
    if sys.stdin.isatty():
        curses.wrapper(tui_main, input_content)
